@login_required
@require_POST
def purge_tenant_sandbox_view(request):
    tenant_id = request.POST.get('tenant_id')
    if not request.user.administered_tenants.filter(id=tenant_id).exists():
        raise PermissionDenied("You are not an administrator of this tenant.")
    call_command('wipe_tenant_sandbox', tenant_id=tenant_id)
    return JsonResponse({'status': 'sandbox data purged', 'tenant_id': tenant_id})
